from itertools import product
import heapq


def _round(n, d, mode):
    if mode == "half_up":
        return (n + d // 2) // d
    return n // d


def _ledger(data, revision_first, discounted, refund):
    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        if revision_first:
            key = (event.get("revision", 0), pos)
        else:
            key = (seq, event.get("revision", 0), pos)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), 10000, mode)
        base = net if discounted else raw
        tax = _round(base * event.get("tax_bp", 0), 10000, mode)
        total = net + tax
        if refund and event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_06(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    options = []
    for name in names:
        versions = sorted({row["version"] for row in packages[name]})
        options.append([-1] + versions)

    best = None
    best_assignment = None
    for vector in product(*options):
        installed = {name: version for name, version in zip(names, vector) if version != -1}
        valid = True
        edges = {name: [] for name in installed}
        required = set()
        constraints = {}

        for name, bounds in data["roots"].items():
            required.add(name)
            constraints.setdefault(name, []).append(tuple(bounds))

        for name, version in installed.items():
            if version in blocked.get(name, []) or (name in pins and pins[name] != version):
                valid = False
                break
            row = next((r for r in packages[name] if r["version"] == version), None)
            if row is None:
                valid = False
                break
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                depname = dep["name"]
                required.add(depname)
                constraints.setdefault(depname, []).append((dep["min"], dep["max"]))
                edges[name].append(depname)

        if not valid or set(installed) != required:
            continue
        for name, ranges in constraints.items():
            version = installed.get(name)
            if version is None or any(not low <= version <= high for low, high in ranges):
                valid = False
                break
        if not valid:
            continue

        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for other in edges.get(name, []):
                if not visit(other):
                    return False
            state[name] = 2
            return True

        if not all(visit(name) for name in installed):
            continue
        if best is None or vector > best:
            best = vector
            best_assignment = installed

    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_assignment}


def _component_07(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    available = [job for job in jobs if job["id"] not in blocked]
    by_id = {job["id"]: job for job in jobs}
    if not mandatory.issubset(by_id) or mandatory & blocked or len(available) < k:
        return {"error": "impossible"}

    best_value = None
    best_ids = None
    for chosen in _subsets(available, k):
        ids = tuple(sorted(job["id"] for job in chosen))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in chosen:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        if any(sum(job["start"] <= t < job["end"] for job in chosen) > 2
               for t in {job["start"] for job in chosen}):
            continue
        value = sum(job["value"] for job in chosen)
        if best_value is None or value > best_value or (value == best_value and ids < best_ids):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _subsets(items, k):
    # Small bounded search without importing another combinatorics helper.
    n = len(items)
    for mask in range(1 << n):
        if mask.bit_count() == k:
            yield [items[i] for i in range(n) if mask >> i & 1]


def _component_08(data):
    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start = data["source"]
    initial_mask = bit_for.get(start, 0)
    start_time = data["start"]
    start_state = (start, initial_mask, data["coupons"])
    distances = {start_state: start_time}
    queue = [(start_time, start, initial_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], coupons)]
            if coupons:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                choices.append((duration, coupons - 1))
            for duration, remaining in choices:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                next_state = (next_node, next_mask, remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, remaining))
    return {"arrival": None}


SOLVERS = {
    "component_01": lambda d: _ledger(d, True, True, True),
    "component_02": lambda d: _ledger(d, False, True, True),
    "component_03": lambda d: _ledger(d, True, False, False),
    "component_04": lambda d: _ledger(d, False, False, False),
    "component_05": lambda d: _ledger(d, True, True, False),
    "component_06": _component_06,
    "component_07": _component_07,
    "component_08": _component_08,
}

